script:
var doc = Document;
// Goal: find every element of a kind so the next step can act on them: all walls, the walls tagged
// with a comment, the elements visible in a plan. Collecting is a READ and needs no transaction;
// this script first builds three walls inside a block so the reads have something to find.
// A blank project has levels already; take the lowest one rather than creating another.
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (level == null || l.Elevation < level.Elevation) level = l;
}

var setup = Connector.WithTransaction(doc, () => {
  double z = level.Elevation;
  var pts = new[] { new Autodesk.Revit.DB.XYZ(0, 0, z), new Autodesk.Revit.DB.XYZ(30, 0, z), new Autodesk.Revit.DB.XYZ(30, 30, z) };
  var ids = new System.Collections.Generic.List<long>();
  for (int i = 0; i < 2; i++) {
    var w = Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(pts[i], pts[i + 1]), level.Id, false);
    ids.Add(w.Id.Value);
  }
  var tagged = Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 30, z), new Autodesk.Revit.DB.XYZ(0, 0, z)), level.Id, false);
  tagged.get_Parameter(Autodesk.Revit.DB.BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set("review");
  ids.Add(tagged.Id.Value);
  doc.Regenerate();
  return ids;
});

// 1. By category. WhereElementIsNotElementType matters: without it the collector also returns
//    every WallType, so "how many walls" comes back too high.
var wallsByCategory = new Autodesk.Revit.DB.FilteredElementCollector(doc)
    .OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_Walls)
    .WhereElementIsNotElementType()
    .ToElementIds();
int typesToo = new Autodesk.Revit.DB.FilteredElementCollector(doc)
    .OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_Walls).GetElementCount();

// 2. By class. OfClass(typeof(Wall)) returns instances only (types are WallType). Prefer OfClass
//    when the API class is what you mean; prefer OfCategory for things that share a class, such as
//    FamilyInstance doors vs windows. Note Room has no native class for OfClass: collect rooms with
//    OfCategory(BuiltInCategory.OST_Rooms).
int wallsByClass = new Autodesk.Revit.DB.FilteredElementCollector(doc)
    .OfClass(typeof(Autodesk.Revit.DB.Wall)).GetElementCount();

// 3. Visible in one view: the (doc, viewId) constructor restricts the collector to elements the
//    view shows. Take the first non-template floor plan; walls on the plan's level are visible in it.
Autodesk.Revit.DB.ViewPlan plan = null;
foreach (Autodesk.Revit.DB.ViewPlan v in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ViewPlan))) {
  if (!v.IsTemplate && v.GenLevel != null && v.GenLevel.Id == level.Id) { plan = v; break; }
}
int wallsInPlan = plan == null ? -1 : new Autodesk.Revit.DB.FilteredElementCollector(doc, plan.Id)
    .OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_Walls).WhereElementIsNotElementType().GetElementCount();

// 4. By parameter value: a rule (this parameter equals "review") wrapped in an
//    ElementParameterFilter, combined with the category filter by chaining. The parameter is
//    named by its BuiltInParameter id, never by its display name.
var commentsId = new Autodesk.Revit.DB.ElementId(Autodesk.Revit.DB.BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS);
var rule = new Autodesk.Revit.DB.FilterStringRule(new Autodesk.Revit.DB.ParameterValueProvider(commentsId),
    new Autodesk.Revit.DB.FilterStringEquals(), "review");
var byComment = new Autodesk.Revit.DB.FilteredElementCollector(doc)
    .OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_Walls)
    .WhereElementIsNotElementType()
    .WherePasses(new Autodesk.Revit.DB.ElementParameterFilter(rule))
    .ToElementIds();

// 5. Combining two filters explicitly: LogicalAndFilter takes ElementFilter objects, useful when
//    the filters are built dynamically rather than chained.
var both = new Autodesk.Revit.DB.LogicalAndFilter(
    new Autodesk.Revit.DB.ElementCategoryFilter(Autodesk.Revit.DB.BuiltInCategory.OST_Walls),
    new Autodesk.Revit.DB.ElementParameterFilter(rule));
int viaLogicalAnd = new Autodesk.Revit.DB.FilteredElementCollector(doc).WherePasses(both).WhereElementIsNotElementType().GetElementCount();

// 6. Return a projection: ids and counts. Returning the elements themselves has no display form.
var reviewIds = new System.Collections.Generic.List<long>();
foreach (var id in byComment) reviewIds.Add(id.Value);
return new {
  createdWallIds = setup,
  wallsByCategory = wallsByCategory.Count, wallsByClass, categoryCountIncludingTypes = typesToo,
  wallsInPlan, planView = plan == null ? null : plan.Name,
  wallsCommentedReview = reviewIds, viaLogicalAnd,
  consistent = wallsByCategory.Count == wallsByClass && viaLogicalAnd == reviewIds.Count
};
